import {pinch} from "@hoge1e3/pinch";
import * as assert from "assert";
export async function main(){
  await this.widget({wmain});
  const vp=document.querySelector("#vp");
  const c=document.querySelector("#cont");
  const pinchc=pinch(c,vp);  
  const ctx=c.getContext("2d");
  ctx.fillStyle="#ddd";
  ctx.fillRect(0,0,200,200);
  c.addEventListener("touchmove",(e)=>{
    const t=e.touches[0];
    const rc=c.getBoundingClientRect();
    /*const rv=vp.getBoundingClientRect();
    const ro={
      x:(rc.x-rv.x),
      y:(rc.y-rv.y),
    };
    console.log(rc, t.clientX,t.clientY);*/
    ctx.fillStyle="#000";
    const s=1/pinchc.transform.scale;
    ctx.fillRect((t.clientX-rc.x)*s, (t.clientY-rc.y)*s,2,2);  
  });
}    
function wmain({t}){
  return t.div(
    t.h1("ace"),
    t.div({
      id:"vp",
      style:`
      background-color: cyan;
      width:200px;
      height:200px;
      overflow:hidden;
      `
    },t.canvas({
      id:"cont",width: 200, height:200,
      }))
  );
}
